# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, N, E, M, G, V = "Lucas", "Nuria", "Ernesto", "Marta", "Alejandra", "Vicente"
D = [
("#", "Escena 1 · Lunes 17 de febrero, 10:15 · Estudio de diseño", "장면 1 · 2월 17일 월요일 오전 10시 15분 · 디자인 스튜디오"),
(None, "Una sala luminosa en el primer piso. En las paredes, decenas de piezas colgadas como cuadros: mármoles, maderas, cementos. Nuria Beltrán, treinta y pocos años, gafas de pasta y auriculares al cuello, tiene en la pantalla una imagen ampliada de una veta blanca.", "2층의 밝은 방. 벽에는 대리석, 나무, 시멘트 무늬 타일 수십 장이 그림처럼 걸려 있다. 30대 초반의 누리아 벨트란이 뿔테 안경에 헤드폰을 목에 걸고, 화면에 흰 결을 크게 확대해 놓고 있다."),
(N, "Pasa, pasa. Ya me ha contado Amparo lo del blanco «muy frío». Me ha dolido en el alma.", "들어와, 들어와. 암파로한테 '너무 차가운' 흰색 얘기 들었어. 마음이 아프더라."),
(L, "¿Por qué? ¿Es tu diseño?", "왜? 네 디자인이야?"),
(N, "Es mi niño. Lo diseñé hace tres años, cuando todavía teníamos los tres hornos en marcha. Pero vale, el cliente manda.", "내 자식 같은 거야. 3년 전에, 아직 가마 세 개가 다 돌아갈 때 디자인했어. 근데 좋아, 고객이 왕이지."),
(L, "El arquitecto quiere un blanco más cálido, tirando a crema. Y una versión antideslizante para los baños.", "건축가는 더 따뜻한, 크림빛 도는 흰색을 원해. 그리고 욕실용 미끄럼 방지 버전도."),
(N, "Lo del antideslizante es fácil: mismo diseño, otro esmalte. Lo del color es más interesante. Mira.", "미끄럼 방지는 쉬워. 같은 디자인에 유약만 바꾸면 돼. 색은 좀 더 재밌어. 봐."),
(None, "Mueve el ratón. La veta gris se vuelve ligeramente dorada; el fondo, de un blanco marfil.", "마우스를 움직인다. 회색 결이 살짝 금빛으로 바뀌고 바탕은 상아빛 흰색이 된다."),
(L, "Uf. Es otro material. Parece más caro.", "와. 완전히 다른 자재 같아. 더 비싸 보여."),
(N, "Eso es lo que quiere un hotel: que parezca más caro de lo que es. Y solo he tocado dos parámetros: el tono del fondo y el color de la veta. La pieza es la misma.", "호텔이 원하는 게 그거야. 실제보다 비싸 보이는 거. 그리고 파라미터 두 개만 건드렸어. 바탕 색조랑 결 색. 타일은 똑같아."),
(L, "¿Y eso se puede fabricar con el mismo esmalte?", "그걸 같은 유약으로 만들 수 있어?"),
(N, "El esmalte base, sí. El color lo pone la impresora. Por eso Pepe dice que yo pinto y él cocina. Pero tengo una idea mejor, si me dejas.", "기본 유약은 같아. 색은 프린터가 입혀. 그래서 페페는 나는 그림 그리고 자기는 요리한다고 해. 근데 허락해 주면 더 좋은 아이디어가 있어."),
(L, "Te escucho.", "말해 봐."),
(N, "Me has dicho que el hotel está en San Pedro, en Monterrey, ¿no? Pues he estado mirando fotos. Detrás de la ciudad hay una montaña con una silueta muy rara.", "호텔이 몬테레이 산페드로에 있다고 했지? 사진을 좀 찾아봤어. 도시 뒤에 실루엣이 아주 독특한 산이 있더라."),
(L, "El Cerro de la Silla. Alejandra me lo mencionó. Dice que se ve desde su oficina.", "세로 데 라 시야. 알레한드라가 말했어. 자기 사무실에서 보인대."),
(N, "Exacto. Pues imagina que en el vestíbulo, en el centro, la veta del mármol dibuja esa silueta. Muy sutil. Solo la ves si te fijas.", "맞아. 로비 한가운데에서 대리석 결이 그 실루엣을 그린다고 상상해 봐. 아주 은은하게. 유심히 봐야만 보이는 거지."),
(L, "¿Cómo lo has visto tan rápido?", "그걸 어떻게 그렇게 빨리 찾았어?"),
(N, "Cuando diseño para un sitio, primero miro el sitio. Es la regla número uno. Bueno, después de tomarme un café.", "어떤 장소를 위해 디자인할 땐 먼저 그 장소를 봐. 그게 제1원칙이야. 음, 커피 마신 다음에."),
(L, "¿Un diseño solo para ellos?", "그 사람들만을 위한 디자인?"),
(N, "Un diseño exclusivo. Lo que no tienen los italianos con su catálogo de siempre.", "전용 디자인. 이탈리아 사람들이 늘 쓰는 카탈로그로는 못 하는 거."),
(L, "Me encanta. ¿Cuánto tiempo necesitas?", "완전 좋아. 시간은 얼마나 필요해?"),
(N, "Para el diseño, tres días. Para fabricar una pieza de muestra, depende de Pepe y del horno.", "디자인은 사흘. 샘플 한 장 굽는 건 페페랑 가마에 달렸고."),
(L, "Alejandra quiere ver una placa grande, de las de tres metros.", "알레한드라는 큰 판을 보고 싶어 해. 3미터짜리."),
(N, "¿Tres metros? ¿En avión? Eso no te lo deja subir ninguna compañía sin un ataúd de madera.", "3미터? 비행기로? 그건 나무 관짝 없이는 어떤 항공사도 안 실어 줘."),
(L, "Amparo dijo lo mismo, con otras palabras. ¿Y un trozo?", "암파로도 다른 말로 똑같이 했어. 조각은?"),
(N, "Un trozo de uno veinte por sesenta, cortado de una placa grande. Se ve el grosor, se ve el corte y cabe en una caja normal.", "큰 판에서 잘라 낸 120×60 조각. 두께도 보이고 절단면도 보이고, 일반 상자에 들어가."),
(L, "Perfecto. Hazlo así, para que puedan tocarlo con las manos.", "완벽해. 그렇게 해 줘. 직접 손으로 만져 볼 수 있게."),
(N, "Una cosa, Lucas. Como esto es un diseño nuevo, tienes que pedirle a Vicente que me deje usar la impresora grande una mañana.", "하나만, 루카스. 이건 새 디자인이니까 비센테한테 대형 프린터를 오전 한나절 쓰게 해 달라고 부탁해야 해."),
(L, "Hecho. Y si dice que no, le enseño la montaña.", "알았어. 안 된다고 하면 그 산을 보여 줄게."),
(N, "(ríe) Así me gusta. Oye, ¿y cómo se llama el diseño? Un diseño sin nombre no se vende.", "(웃으며) 그래야지. 근데 디자인 이름은 뭐로 해? 이름 없는 디자인은 안 팔려."),
(L, "«Blanco San Pedro». Por el barrio del hotel. Suena a hotel caro, ¿no?", "‘블랑코 산페드로’. 호텔이 있는 동네 이름으로. 비싼 호텔 같은 이름이지?"),

("#", "Escena 2 · Martes 25 de febrero, 16:40 · Despacho de exportación", "장면 2 · 2월 25일 화요일 오후 4시 40분 · 수출팀 사무실"),
(None, "Ocho días después. Las muestras salieron el jueves 20 por mensajería urgente: dos piezas cálidas, una antideslizante y el trozo de gran formato con la silueta de la montaña. Lucas mira la pantalla del seguimiento: «Retenido en aduana». Suena el móvil. Prefijo +52.", "8일 뒤. 샘플은 20일 목요일에 특송으로 나갔다. 따뜻한 색 두 장, 미끄럼 방지 한 장, 산 실루엣이 들어간 대형 판 조각. 루카스가 배송 조회 화면을 본다. '세관 보류'. 휴대폰이 울린다. 국가번호 +52."),
(E, "¿Bueno? ¿El licenciado Lucas Ferrer?", "여보세요? 루카스 페레르 선생님이세요?"),
(L, "Sí, soy yo. ¿Con quién hablo?", "네, 저예요. 누구시죠?"),
(E, "Le habla el licenciado Ernesto Salinas, agente aduanal. La señora Garza me pidió que le llamara por un paquete suyo.", "관세사 에르네스토 살리나스입니다. 가르사 씨가 선생님 소포 건으로 전화를 드리라고 하셨어요."),
(L, "Ah, muchas gracias. Llevo dos días mirando la palabra «retenido». ¿Qué ha pasado?", "아, 정말 감사합니다. 이틀째 '보류'라는 단어만 보고 있었어요. 무슨 일이죠?"),
(E, "Pues mire, el paquete llegó al aeropuerto de Monterrey el viernes, pero la aduana lo detuvo porque la documentación venía incompleta.", "네, 소포는 금요일에 몬테레이 공항에 도착했는데, 서류가 불완전해서 세관이 붙잡았어요."),
(L, "¿Incompleta? La empresa de mensajería me dijo que con la guía era suficiente.", "불완전하다고요? 특송 회사는 운송장만 있으면 된다고 했는데요."),
(E, "Para un sobre con papeles, sí. Para mercancía, no. Faltaba la factura comercial.", "서류 봉투라면 그렇죠. 물품은 아니에요. 상업송장이 빠져 있었어요."),
(L, "¿La factura comercial? Pero si no hay venta, ¿qué factura voy a hacer?", "상업송장이요? 판매가 없는데 무슨 송장을 만들어요?"),
(E, "Una factura que diga qué es, cuánto vale y para qué sirve. Aunque no se cobre. Sin ese papel, el oficial no sabe qué tiene delante.", "이게 뭔지, 얼마짜리인지, 무슨 용도인지 적힌 송장이요. 돈을 안 받더라도요. 그 서류가 없으면 세관 직원은 눈앞에 있는 게 뭔지 몰라요."),
(L, "Pero son muestras. No las vendemos. Por eso pusimos «muestras sin valor comercial».", "하지만 샘플이에요. 파는 게 아니에요. 그래서 '상업적 가치 없는 샘플'이라고 적었어요."),
(E, "Sí, eso lo vi. El problema es que también pusieron valor cero. Y para la aduana nada vale cero, licenciado.", "네, 봤어요. 문제는 가액도 0으로 적었다는 거예요. 세관 입장에선 가치가 0인 물건은 없어요, 선생님."),
(L, "¿Ni siquiera una muestra?", "샘플조차도요?"),
(E, "Ni siquiera. Una pieza de porcelánico de un metro veinte con un diseño impreso... eso tiene un valor. Al oficial le pareció raro y lo mandó a revisión.", "샘플조차도요. 디자인이 인쇄된 1.2미터짜리 자기질 타일이면 가치가 있죠. 세관 직원이 이상하게 여겨서 검사로 넘겼어요."),
(L, "Entiendo. Se me olvidó que una muestra grande no parece una muestra.", "알겠어요. 큰 샘플은 샘플처럼 안 보인다는 걸 깜빡했네요."),
(E, "Le pasa a mucha gente, no se preocupe. Lo que necesitamos es una factura proforma con un valor real, aunque sea pequeño.", "많은 분들이 그래요, 걱정 마세요. 필요한 건 작더라도 실제 가액을 적은 견적 송장이에요."),
(L, "¿Qué valor pongo?", "가액을 얼마로 적죠?"),
(E, "El costo de fabricación, más o menos. No el precio de venta. Y que diga claramente: «muestras sin valor comercial, no destinadas a la venta».", "대략 제조 원가요. 판매가가 아니라. 그리고 분명하게 써 주세요. '상업적 가치 없는 샘플, 판매 목적 아님'."),
(L, "De acuerdo. ¿Y luego?", "알겠습니다. 그다음은요?"),
(E, "Luego yo preparo el pedimento a nombre de la empresa de la señora Garza, que es la importadora, con su RFC.", "그다음엔 제가 수입자인 가르사 씨 회사 명의로 수입신고서를 그 회사 RFC 번호로 준비해요."),
(L, "Perdone, ¿el pedimento? ¿Y el RFC?", "죄송한데, 페디멘토요? RFC는요?"),
(E, "El pedimento es la declaración de importación, el documento oficial de la aduana. Y el RFC es el registro fiscal de la empresa. Como su NIF de ustedes, creo.", "페디멘토는 수입신고서, 세관의 공식 서류예요. RFC는 회사의 납세 등록번호고요. 그쪽의 NIF 같은 거라고 알고 있어요."),
(L, "¿Y eso lo tengo que preparar yo desde aquí?", "그건 제가 여기서 준비해야 하나요?"),
(E, "No, no, eso lo hago yo. Para eso estamos los agentes aduanales. Usted solo mándeme la proforma.", "아뇨, 아뇨, 그건 제가 해요. 그러라고 관세사가 있는 거죠. 선생님은 견적 송장만 보내 주세요."),
(L, "Entendido. ¿Habrá que pagar impuestos?", "알겠어요. 세금을 내야 하나요?"),
(E, "Probablemente algo de IVA y de derechos, pero poca cosa con un valor pequeño. Eso lo paga el importador y luego ustedes se arreglan.", "아마 부가세랑 관세가 조금 붙겠지만 가액이 작으면 얼마 안 돼요. 그건 수입자가 내고 나중에 두 회사가 정산하면 돼요."),
(L, "Entonces se lo descontamos de la primera factura, si hay pedido.", "그럼 주문이 생기면 첫 송장에서 그만큼 빼 드릴게요."),
(E, "Eso ya lo hablan ustedes con la señora Garza. Yo solo le digo cuánto es cuando lo sepa.", "그건 가르사 씨랑 얘기하세요. 저는 금액이 나오면 알려 드리기만 할게요."),
(L, "¿Cuándo cree que podrán salir las muestras?", "샘플이 언제쯤 나올 수 있을까요?"),
(E, "Si me manda la proforma hoy, y no hay más sorpresas, el lunes o el martes. Cuando tenga el documento, lo presento inmediatamente.", "오늘 견적 송장을 보내 주시고 더 이상 변수가 없으면 월요일이나 화요일이요. 서류 받는 대로 바로 제출할게요."),
(L, "Se la mando en una hora. Muchísimas gracias, licenciado Salinas.", "한 시간 안에 보내 드릴게요. 정말 감사합니다, 살리나스 선생님."),
(E, "A sus órdenes. Y un consejo para la próxima: que su mensajería ofrezca servicio de agente aduanal. Se ahorra mucho tiempo.", "별말씀을요. 그리고 다음을 위한 조언 하나 드리면, 특송 회사가 통관 대행 서비스를 해 주는지 확인하세요. 시간이 훨씬 절약돼요."),
(None, "Lucas cuelga y se frota la cara. Abre una plantilla de factura en blanco. Luego cierra el documento y busca otro número en su agenda.", "루카스가 전화를 끊고 얼굴을 문지른다. 빈 송장 양식을 연다. 그러다 문서를 닫고 연락처에서 다른 번호를 찾는다."),

("#", "Escena 3 · Martes 25 de febrero, 17:30 · Videollamada con ICEX", "장면 3 · 2월 25일 화요일 오후 5시 30분 · ICEX와 화상 통화"),
(M, "¡Lucas! Qué alegría. Desde el curso de Madrid no sabía nada de ti. ¿Ya estás en Castellón?", "루카스! 반갑다. 마드리드 연수 이후로 소식이 없더니. 벌써 카스테욘이야?"),
(L, "En Onda, entre hornos y naranjos. Marta, perdona que te llame así, sin avisar. Tengo unas muestras retenidas en la aduana de Monterrey.", "온다야, 가마랑 오렌지 나무 사이에서. 마르타, 이렇게 갑자기 연락해서 미안해. 몬테레이 세관에 샘플이 묶여 있어."),
(M, "Ay, el clásico. ¿Valor cero?", "아, 단골 문제네. 가액 0?"),
(L, "¿Cómo lo sabes?", "어떻게 알았어?"),
(M, "Porque es el error número uno. Me lo cuentan tres empresas al mes. ¿Ya tienes agente aduanal allí?", "제일 흔한 실수거든. 한 달에 세 회사는 그 얘기를 해. 거기 관세사는 있어?"),
(L, "Sí, el de la clienta. Me ha pedido una proforma con valor real. Te llamo porque no quiero que esto me vuelva a pasar.", "응, 고객 쪽 관세사. 실제 가액을 적은 견적 송장을 달래. 다시는 이런 일이 없게 하고 싶어서 전화했어."),
(M, "Muy bien. Entonces te doy tres reglas. Apunta.", "좋아. 그럼 규칙 세 가지 알려 줄게. 적어."),
(L, "Apuntando.", "적고 있어."),
(M, "Primera: nunca valor cero. Pon un valor simbólico pero creíble, el coste de producción. Segunda: describe bien la mercancía. No pongas «muestras», pon «baldosas cerámicas de porcelánico, muestras sin valor comercial», con medidas y peso.", "첫째, 절대 가액 0은 안 돼. 상징적이지만 믿을 만한 가액, 그러니까 생산 원가를 적어. 둘째, 물품 설명을 제대로 해. '샘플'이라고만 쓰지 말고 '자기질 세라믹 타일, 상업적 가치 없는 샘플'이라고, 치수와 무게까지 써."),
(L, "¿Y la tercera?", "셋째는?"),
(M, "La tercera es la más importante: antes de enviar nada a un país nuevo, pregunta al importador qué necesita su aduana. Ellos lo saben mejor que nadie.", "셋째가 제일 중요해. 새로운 나라에 뭘 보내기 전에, 수입자한테 그쪽 세관이 뭘 요구하는지 물어봐. 그 사람들이 누구보다 잘 알아."),
(L, "Tiene sentido. Yo pensé que, como eran muestras, no hacía falta.", "일리 있네. 난 샘플이니까 필요 없을 줄 알았어."),
(M, "Ya. Y como nadie te lo había dicho, lo has aprendido pagando. Es la mejor manera de no olvidarlo.", "그렇지. 아무도 말해 주지 않았으니 대가를 치르고 배운 거야. 그래야 안 잊어버려."),
(L, "Oye, ya que te tengo: el ingeniero de la clienta me preguntó por la norma mexicana para baldosas. ¿Nuestros ensayos europeos sirven allí?", "참, 연결된 김에. 고객사 엔지니어가 멕시코 타일 규격을 물었어. 우리 유럽 시험 결과가 거기서도 통해?"),
(M, "A veces sí y a veces no. Depende del proyecto y de lo que pida la constructora. Te paso el contacto de nuestra oficina comercial en México; ellos te dirán qué laboratorio reconoce allí la norma.", "통할 때도 있고 아닐 때도 있어. 프로젝트랑 건설사 요구에 따라 달라. 멕시코에 있는 우리 상무관실 연락처 줄게. 거기서 어느 시험기관이 그 규격을 인정받는지 알려 줄 거야."),
(L, "Genial. ¿Y eso cuesta algo?", "좋다. 그거 비용 들어?"),
(M, "Una primera consulta, no. Si necesitas un estudio de mercado completo, sí. Pero para ti, de momento, con un par de correos basta.", "첫 상담은 무료야. 전체 시장 조사가 필요하면 비용이 들고. 근데 지금 너한테는 메일 몇 통이면 충분해."),
(L, "¿Y si al final la norma europea no vale? ¿Hay que repetir todos los ensayos?", "결국 유럽 규격이 안 통하면? 시험을 전부 다시 해야 해?"),
(M, "No siempre todos. A veces basta con que un laboratorio de allí revise los vuestros. Pero no lo des por hecho hasta que lo confirmes.", "꼭 전부는 아니야. 거기 시험기관이 너희 결과를 검토하는 걸로 충분할 때도 있어. 근데 확인하기 전엔 당연하다고 생각하지 마."),
(L, "Entendido. No prometer lo que no sé. Ya me lo han dicho dos veces este mes.", "알았어. 모르는 건 약속하지 말 것. 이번 달에만 두 번째 듣는 말이야."),
(M, "¿Quién más te lo ha dicho?", "또 누가 그랬는데?"),
(L, "La hija del jefe. Que, por cierto, no me quiere mucho.", "사장 딸. 참고로 날 별로 안 좋아해."),
(M, "Pues hazle caso. Las que no te quieren suelen decirte las verdades más útiles.", "그럼 그 사람 말 들어. 널 안 좋아하는 사람들이 보통 제일 쓸모 있는 진실을 말해 줘."),
(L, "Gracias, Marta. Te debo una.", "고마워, 마르타. 신세 졌다."),
(M, "Me debes una visita a Onda. Dicen que la Magdalena de Castellón no se la puede perder nadie.", "온다 방문 한 번으로 갚아. 카스테욘 마그달레나 축제는 아무도 놓치면 안 된다며."),
(L, "Ya te contaré. Todavía no sé ni qué es.", "나중에 얘기해 줄게. 아직 그게 뭔지도 몰라."),
(M, "Pues infórmate, que es en marzo. Y Lucas: para que no te pase otra vez, hazte una lista de comprobación para cada envío.", "알아봐, 3월이야. 그리고 루카스, 또 이런 일 없게 발송할 때마다 체크리스트를 만들어 둬."),
(L, "Una lista de comprobación. Eso lo hacía yo en la consultora para todo el mundo. Y ahora se me había olvidado hacerla para mí.", "체크리스트라. 컨설팅 회사에선 다른 사람들한테 그걸 만들어 주던 게 나였는데. 정작 나한테는 만드는 걸 잊었네."),

("#", "Escena 4 · Jueves 6 de marzo, 18:05 · Pasillo de las oficinas", "장면 4 · 3월 6일 목요일 오후 6시 5분 · 사무동 복도"),
(None, "Nueve días más tarde. Las muestras salieron de la aduana el lunes 3 y llegaron a la oficina de Alejandra el miércoles. Lucas camina por el pasillo con el móvil en la oreja.", "9일 뒤. 샘플은 3일 월요일에 세관을 통과해 수요일에 알레한드라의 사무실에 도착했다. 루카스가 휴대폰을 귀에 댄 채 복도를 걷는다."),
(G, "Licenciado, ¿me escucha? Le hablo desde la obra, hay mucho ruido.", "선생님, 들리세요? 공사 현장에서 전화하는 거라 시끄러워요."),
(L, "La oigo bien, señora Garza. ¿Qué le han parecido?", "잘 들려요, 가르사 씨. 어떠셨어요?"),
(G, "Mire, le voy a decir la verdad. El blanco cálido le gustó al arquitecto. El antiderrapante, a Rodolfo. Y el pedazo grande...", "저기요, 사실대로 말씀드릴게요. 따뜻한 흰색은 건축가가 마음에 들어 했어요. 미끄럼 방지는 로돌포가요. 그리고 그 큰 조각은…"),
(L, "¿Y el pedazo grande?", "큰 조각은요?"),
(G, "El pedazo grande lo tengo aquí, en mi escritorio. Nadie me había hecho nunca un diseño con el Cerro de la Silla. ¿De quién fue la idea?", "그 큰 조각은 지금 여기 제 책상에 있어요. 세로 데 라 시야를 디자인에 넣어 준 사람은 지금까지 아무도 없었어요. 누구 아이디어였어요?"),
(L, "De Nuria, nuestra diseñadora. Se lo diré. Se va a poner muy contenta.", "저희 디자이너 누리아요. 전해 줄게요. 아주 기뻐할 거예요."),
(G, "El arquitecto quiere ponerla en el centro del vestíbulo, justo debajo de la lámpara grande. Dice que la gente se va a quedar mirando el piso.", "건축가가 그걸 로비 한가운데, 큰 샹들리에 바로 아래 놓고 싶대요. 사람들이 바닥을 한참 쳐다볼 거래요."),
(L, "Eso es exactamente lo que buscaba Nuria. Que solo lo vean los que se fijan.", "그게 바로 누리아가 원한 거예요. 유심히 보는 사람만 볼 수 있게요."),
(G, "Dígaselo. Y dígale también que los italianos no hicieron nada parecido. Eso no quiere decir que ya ganaron, ¿eh? Todavía espero la oferta.", "전해 주세요. 그리고 이탈리아 쪽은 비슷한 것도 안 했다고도요. 그렇다고 벌써 이긴 건 아니에요, 아셨죠? 아직 견적을 기다리고 있어요."),
(L, "La tendrá. Y perdone otra vez por lo de la aduana.", "받으실 거예요. 그리고 세관 일은 다시 한번 죄송합니다."),
(G, "Ni se preocupe. Ernesto dice que usted aprende rápido. Aquí eso vale más que el precio. Bueno, casi.", "걱정 마세요. 에르네스토가 선생님은 배우는 게 빠르대요. 여기선 그게 가격보다 더 중요해요. 음, 거의요."),
(L, "¿Cuándo necesita exactamente la oferta?", "견적은 정확히 언제 필요하세요?"),
(G, "Le dije dos semanas, ¿verdad? Pues con lo de la aduana, le doy hasta finales de marzo. Pero no me haga esperar más, que el italiano llama todos los días.", "2주라고 했죠? 세관 일도 있었으니 3월 말까지 드릴게요. 근데 더는 기다리게 하지 마세요. 이탈리아 쪽은 매일 전화해요."),
(L, "Finales de marzo. Se lo confirmo por escrito hoy mismo.", "3월 말이요. 오늘 바로 서면으로 확인해 드릴게요."),
(G, "Ándale. Que le vaya bonito, licenciado. Y salúdeme a Nuria.", "좋아요. 잘 지내세요, 선생님. 누리아한테도 안부 전해 주세요."),
(None, "Lucas cuelga sonriendo. Vicente sale de su despacho con el abrigo puesto.", "루카스가 웃으며 전화를 끊는다. 비센테가 코트를 입은 채 자기 방에서 나온다."),
(V, "Esa cara es de buenas noticias. ¿Era Monterrey?", "그 얼굴은 좋은 소식이네요. 몬테레이였어요?"),
(L, "Era Monterrey. Les ha encantado el diseño de Nuria. La montaña.", "몬테레이였어요. 누리아 디자인을 아주 좋아했어요. 그 산이요."),
(V, "Ya me lo ha enseñado Nuria. Tres veces. (sonríe) Me ha dicho que tú le diste permiso para usar la impresora grande.", "누리아가 벌써 보여 줬어요. 세 번이나. (웃으며) 당신이 대형 프린터 써도 된다고 허락했다던데요."),
(L, "¿Y qué te ha parecido?", "어떻게 보셨어요?"),
(V, "Que mi abuelo habría dicho que es demasiado moderno. Y luego lo habría puesto en el suelo de su casa.", "할아버지라면 너무 현대적이라고 하셨을 거예요. 그러고는 자기 집 바닥에 까셨겠죠."),
(L, "Bueno... le dije que te lo pediría.", "음… 당신한테 부탁해 보겠다고 했죠."),
(V, "Y luego se te olvidó pedírmelo.", "그리고 나한테 부탁하는 걸 잊었고요."),
(L, "Se me pasó con lo de la aduana. Lo siento.", "세관 일 때문에 깜빡했어요. 죄송해요."),
(V, "No pasa nada. Para la próxima, pide primero y celebra después. Oye, ¿qué haces el sábado 22?", "괜찮아요. 다음엔 먼저 부탁하고 축하는 나중에 해요. 그건 그렇고, 22일 토요일에 뭐 해요?"),
(L, "¿El 22? Nada, supongo. ¿Por qué?", "22일이요? 아무것도 없을걸요. 왜요?"),
(V, "Porque es la Magdalena, las fiestas de Castellón. Si quieres entender esta tierra, tienes que venir. Mascletà a las dos, cena con la familia y desfile por la noche.", "마그달레나거든요, 카스테욘 축제. 이 땅을 이해하고 싶으면 와야 해요. 2시에 마스클레타, 가족과 저녁, 밤에는 행렬."),
(L, "¿Mascletà?", "마스클레타요?"),
(V, "Petardos. Muchos petardos. A las dos de la tarde, en una plaza. Tú tráete tapones para los oídos y hambre.", "폭죽이요. 엄청 많은 폭죽. 오후 2시에 광장에서. 귀마개랑 배고픔만 챙겨 와요."),
(L, "¿Y no es peligroso?", "위험하지 않아요?"),
(V, "Es Castellón, Lucas. Aquí los niños aprenden antes a encender una traca que a montar en bici.", "카스테욘이에요, 루카스. 여기 애들은 자전거 타는 것보다 폭죽 줄에 불 붙이는 걸 먼저 배워요."),
(L, "Allí estaré. Una amiga de Madrid me ha dicho que no me la puedo perder.", "갈게요. 마드리드 친구도 놓치면 안 된다고 했어요."),
(V, "Tu amiga tiene razón. Y no te preocupes por la oferta de Monterrey. Cuando estés en la fiesta, ya hablaremos de todo. Aquí las cosas importantes...", "친구 말이 맞아요. 그리고 몬테레이 견적은 걱정 마요. 축제에 오면 다 얘기합시다. 여기선 중요한 일은…"),
(L, "...se hablan comiendo. Ya lo sé.", "…먹으면서 얘기한다. 알아요."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "알레한드라가 요구한 2차 샘플을 준비하는 3주. 디자이너 누리아는 몬테레이의 상징인 세로 데 라 시야 산의 실루엣을 대리석 결 속에 숨긴 전용 디자인을 제안한다. 그런데 특송으로 보낸 샘플이 몬테레이 세관에 묶인다. 루카스는 관세사 에르네스토 살리나스에게 '가액 0'의 함정, 상업송장, 수입신고서(pedimento), RFC를 배우고, ICEX의 옛 동료 마르타 오르티스에게서 발송 규칙 세 가지를 듣는다. 샘플이 마침내 도착하고, 비센테는 루카스를 카스테욘 축제에 초대한다.",
 "듣기 질문 ① 누리아가 제안한 전용 디자인의 아이디어는 무엇이고, 왜 이탈리아 업체와의 차별점이 되는가?",
 "듣기 질문 ② 샘플이 세관에 묶인 이유는 무엇이며, 에르네스토는 어떻게 해결하라고 하는가?",
 "듣기 질문 ③ 마르타가 알려 준 발송 규칙 세 가지는?",
]),
]

